  "tbFile": "tb/tb_top.sv",
  "rtl": "`timescale 1ns/1ps\n\nmodule arbiter (\n    input  logic       clk,\n    input  logic       rst,\n    input  logic [3:0] req,\n    output logic [3:0] grant\n);\n\n    always_ff @(posedge clk) begin\n        if (rst) begin\n            grant <= 4'b0000;\n        end\n        else begin\n            casex (req)\n                4'b1xxx: grant <= 4'd8;\n                4'b01xx: grant <= 4'd4;\n                4'b001x: grant <= 4'd2;\n                4'b0001: grant <= 4'd1;\n                default: grant <= 4'd0;\n            endcase\n        end\n    end\n\nendmodule\n",
  "tb": "`timescale 1ns/1ps\n\ninterface arb_if;\n\n    logic       clk;\n    logic       rst;\n    logic [3:0] req;\n    logic [3:0] grant;\n\nendinterface\n\nclass arb_transaction;\n\n    rand bit [3:0] req;\n\n    logic [3:0] grant;\n\nendclass\n\nclass arb_generator;\n\n    mailbox #(arb_transaction) gen2drv;\n    int n;\n\n    function new\n    (\n        mailbox #(arb_transaction) gen2drv,\n        int n\n    );\n\n        this.gen2drv = gen2drv;\n        this.n       = n;\n\n    endfunction\n\n    task run();\n\n        arb_transaction tr;\n\n        repeat(n)\n        begin\n\n            tr = new();\n\n            if(!tr.randomize())\n                $display(\"Randomization failed\");\n\n            gen2drv.put(tr);\n\n        end\n\n    endtask\n\nendclass\n\nclass arb_driver;\n\n    virtual arb_if vif;\n\n    mailbox #(arb_transaction) gen2drv;\n\n    int n;\n\n    function new\n    (\n        virtual arb_if vif,\n        mailbox #(arb_transaction) gen2drv,\n        int n\n    );\n\n        this.vif     = vif;\n        this.gen2drv = gen2drv;\n        this.n       = n;\n\n    endfunction\n\n    task run();\n\n        arb_transaction tr;\n\n        repeat(n)\n        begin\n\n            gen2drv.get(tr);\n\n            @(negedge vif.clk);\n\n            vif.req = tr.req;\n\n        end\n\n    endtask\n\nendclass\n\nclass arb_monitor;\n\n    virtual arb_if vif;\n\n    mailbox #(arb_transaction) mon2sb;\n    int n;\n\n    function new\n    (\n        virtual arb_if vif,\n        mailbox #(arb_transaction) mon2sb,\n        int n\n    );\n\n        this.vif    = vif;\n        this.mon2sb = mon2sb;\n        this.n      = n;\n\n    endfunction\n\n    task run();\n\n        arb_transaction tr;\n\n        repeat(n)\n        begin\n\n            @(posedge vif.clk);\n\n            tr = new();\n            tr.req = vif.req;\n\n            #1;\n\n            tr.grant = vif.grant;\n            mon2sb.put(tr);\n\n        end\n\n    endtask\n\nendclass\n\nclass arb_scoreboard;\n\n    mailbox #(arb_transaction) mon2sb;\n\n    int n;\n    int pass = 0;\n    int fail = 0;\n\n    function new\n    (\n        mailbox #(arb_transaction) mon2sb,\n        int n\n    );\n\n        this.mon2sb = mon2sb;\n        this.n      = n;\n\n    endfunction\n\n    task run();\n\n        arb_transaction tr;\n        logic [3:0] exp_grant;\n\n        repeat(n)\n        begin\n\n            mon2sb.get(tr);\n\n            casex(tr.req)\n                4'b1xxx: exp_grant = 4'd8;\n                4'b01xx: exp_grant = 4'd4;\n                4'b001x: exp_grant = 4'd2;\n                4'b0001: exp_grant = 4'd1;\n                default: exp_grant = 4'd0;\n            endcase\n\n            if(tr.grant === exp_grant)\n            begin\n\n                pass++;\n\n            end\n\n            else\n            begin\n\n                fail++;\n\n                $display(\n                    \"ERROR: REQ=%b Expected=%b Actual=%b\",\n                    tr.req,\n                    exp_grant,\n                    tr.grant\n                );\n\n            end\n\n        end\n\n        $display(\"PASS = %0d | FAIL = %0d\", pass, fail);\n    endtask\n\nendclass\n\nclass arb_environment;\n\n    virtual arb_if vif;\n\n    mailbox #(arb_transaction) gen2drv;\n    mailbox #(arb_transaction) mon2sb;\n\n    arb_generator  gen;\n    arb_driver     drv;\n    arb_monitor    mon;\n    arb_scoreboard sb;\n    int n;\n\n    function new\n    (\n        virtual arb_if vif,\n        int n\n    );\n\n        this.vif = vif;\n        this.n   = n;\n\n        gen2drv = new();\n        mon2sb  = new();\n        gen = new(\n            gen2drv,\n            n\n        );\n\n        drv = new(\n            vif,\n            gen2drv,\n            n\n        );\n\n        mon = new(\n            vif,\n            mon2sb,\n            n\n        );\n\n        sb = new(\n            mon2sb,\n            n\n        );\n\n    endfunction\n\n    task run();\n\n        fork\n\n            gen.run();\n            drv.run();\n            mon.run();\n            sb.run();\n\n        join\n\n    endtask\n\nendclass\n\nmodule tb_top;\n\n    parameter int N = 100;\n\n    arb_if intf();\n\n    arbiter dut\n    (\n        .clk   (intf.clk),\n        .rst   (intf.rst),\n        .req   (intf.req),\n        .grant (intf.grant)\n    );\n\n    arb_environment env;\n\n    initial\n    begin\n\n        intf.clk = 0;\n\n        forever #5\n            intf.clk = ~intf.clk;\n\n    end\n\n    initial\n    begin\n\n        intf.rst = 1;\n        intf.req = 0;\n\n        repeat(2)\n            @(posedge intf.clk);\n\n        #1;\n\n        intf.rst = 0;\n\n        env = new(\n            intf,\n            N\n        );\n\n        env.run();\n        $finish;\n\n    end\n\nendmodule\n"
